sys_script_include.script:
var IAWPayloadFormatter = Class.create();
IAWPayloadFormatter.prototype = {
    initialize: function() {},
    format_btmh: function(payload) {
        var in_payload = JSON.parse(payload);
        var out_payload = {};
        out_payload.ctac_trade_id = in_payload.data[0].payload.CTAC_TRADE_DID;
        out_payload.counterparty_code = in_payload.data[0].payload.CTAC_TRADE_AUDIT[0].COUNTERPARTY_CODE;
        out_payload.trading_entity_id = in_payload.data[0].payload.CTAC_TRADE_AUDIT[0].TRADING_ENTITY_ID;
        out_payload.buy_sell = in_payload.data[0].payload.CTAC_TRADE_AUDIT[0].BUY_SELL;
        out_payload.exchange_id = in_payload.data[0].payload.CTAC_TRADE_AUDIT[0].EXCHANGE_ID;
        out_payload.ctac_ctm_trade_level_fld_comp = in_payload.data[0].payload.CTAC_CTM_TRADE_LEVEL_FLD_COMP;
        return out_payload;
    },
    format_fcih: function(payload) {
        var in_payload = JSON.parse(payload);
        var out_payload = {};
        out_payload.ctac_trade_id = in_payload.data[0].payload.CTAC_TRADE_DID;
        out_payload.counterparty_code = in_payload.data[0].payload.CTAC_TRADE_AUDIT[0].COUNTERPARTY_CODE;
        out_payload.ctac_trans_msg_p1 = in_payload.data[0].payload.CTAC_TRANS_MSG_P1;
        out_payload.counterparty_account = in_payload.data[0].payload.COUNTERPARTY_ACCOUNT;
        return out_payload;
    },
    format_cuh: function(payload) {
        var in_payload = JSON.parse(payload);
        var out_payload = {};
        out_payload.ctac_trade_id = in_payload.data[0].payload.CTAC_TRADE_DID;
        out_payload.counterparty_code = in_payload.data[0].payload.CTAC_TRADE_AUDIT[0].COUNTERPARTY_CODE;
        out_payload.ctac_allocation_id = in_payload.data[0].payload.CTAC_ALLOCATION_DID;
        out_payload.subaccount_view = in_payload.data[0].payload.CTAC_TRADE_AUDIT[0].COUNTERPARTY_DESCRIPTION;
        return out_payload;
    },
    format_almh: function(payload) {
        var in_payload = JSON.parse(payload);
        var out_payload = {};
        out_payload.ctac_trade_id = in_payload.data[0].payload.CTAC_TRADE_DID;
        out_payload.counterparty_code = in_payload.data[0].payload.CTAC_TRADE_AUDIT[0].COUNTERPARTY_CODE;
        out_payload.ctac_allocation_id = in_payload.data[0].payload.CTAC_ALLOCATION_DID;
        out_payload.trading_entity_id = in_payload.data[0].payload.CTAC_TRADE_AUDIT[0].TRADING_ENTITY_ID;
        out_payload.buy_sell = in_payload.data[0].payload.CTAC_TRADE_AUDIT[0].BUY_SELL;
        out_payload.exchange_id = in_payload.data[0].payload.CTAC_TRADE_AUDIT[0].EXCHANGE_ID;
        out_payload.ctac_ctm_trade_detail_fld_comp = in_payload.data[0].payload.CTAC_CTM_TRADE_DETAIL_FLD_COMP;
        return out_payload;
    },
    format_maih: function(payload, allocation_details) {
        var in_payload = JSON.parse(payload);
        var in_counterparty_account = in_payload.data[0].payload.COUNTERPARTY_ACCOUNT;
        var in_allocation_details = JSON.parse(allocation_details);
        var out_payload = {};
        var blockTradeDate = this._dateFix(in_payload.data[0].payload.CTAC_TRADE_AUDIT[0].CTAC_TRADE_DATE);
        var blockValueDate = this._dateFix(in_payload.data[0].payload.CTAC_TRADE_AUDIT[0].VALUE_DATE);
        var blockTradeInstrumentCode = this._getInstrumentCode(in_payload.data[0].payload.CTAC_TRADE_AUDIT[0], in_allocation_details[0].Financial_Instrument_Identifier_Type);
        var blockTradeCommission = this._getTradeCommission(in_payload.data[0].payload.CTAC_TRADE_CHARGES);

        var block_trade_details = {
            BLOCK_TRADE_ID: in_payload.data[0].payload.CTAC_TRADE_DID,
            COUNTERPARTY_CODE: in_payload.data[0].payload.CTAC_TRADE_AUDIT[0].COUNTERPARTY_CODE,
            INSTRUMENT_CODE: blockTradeInstrumentCode,
            TRADE_DATE: blockTradeDate,
            BUY_SELL: in_payload.data[0].payload.CTAC_TRADE_AUDIT[0].BUY_SELL,
            GROSS_PRICE: Number(in_payload.data[0].payload.CTAC_TRADE_AUDIT[0].GROSS_PRICE),
            QUANTITY: Number(in_payload.data[0].payload.CTAC_TRADE_AUDIT[0].CTAC_TRADE_QUANTITY),
            TRADING_CCY: in_payload.data[0].payload.CTAC_TRADE_AUDIT[0].CTAC_DEALT_CCY,
            VALUE_DATE: blockValueDate,
            ACOMMISSION: blockTradeCommission,
            NET_NET_CONSIDERATION: in_payload.data[0].payload.CTAC_TRADE_AUDIT[0].NET_NET_CONSIDERATION,

        };

        var client_allocation_collection = [];

        for (let i = 0; i < in_allocation_details.length; i++) {


            //var subAccountView = this.getSubAccountView(in_allocation_details[i].Sub_Account_Identifier, in_counterparty_account);
            var allocationDirection = this._directionBuySell(in_allocation_details[i].Direction);

            var client_allocation_object = {
                QUANTITY: in_allocation_details[i].Allocation_Quantity,
                SUBACCOUNT_VIEW: in_allocation_details[i].Sub_Account_Identifier,
                INSTRUMENT_CODE: in_allocation_details[i].Financial_Instrument_Identifier,
                TRADE_DATE: in_allocation_details[i].Trade_Date,
                BUY_SELL: allocationDirection,
                GROSS_PRICE: Number(in_allocation_details[i].Gross_Price),
                CURRENCY: "", //We don't get this from SWB, so leaving it blank
                VALUE_DATE: in_allocation_details[i].Value_Date,
                COMMISSION: Number(in_allocation_details[i].Commission),
                CONSIDERATION: Number(in_allocation_details[i].Net_Consideration),

            };
            client_allocation_collection.push(client_allocation_object);

        }

        out_payload.block_trade_details = block_trade_details;
        out_payload.client_allocation_details = client_allocation_collection;

        return out_payload;
    },

    _dateFix: function(dateString) {
        //this function switches the date into format required by the IAW API
        var apiDateFormat = dateString.slice(4, 6) + "/" + dateString.slice(6, 8) + "/" + dateString.slice(0, 4);
        return apiDateFormat;
    },

    _getInstrumentCode: function(ctacTradeAudit, financialInstrumentType) {
        //this function gets the correct Instrument Code from the CTAC Payload, based on the Financial Instrument Type returned from SWB
        if (ctacTradeAudit && financialInstrumentType) {

            //get the Financial Instrument Mapping from the system property
            var instrumentMapping = JSON.parse(gs.getProperty('x_hsb11_iaw_widget.swb_ctac_instrument_mapping'));

            //loop through outcomeMapping to get the IAW Response from responseCode
            for (let i = 0; i < instrumentMapping.length; i++) {
                if (instrumentMapping[i].SWB_INSTRUMENT_TYPE == financialInstrumentType) {
                    var ctacInstrument = instrumentMapping[i].CTAC_INSTRUMENT;

                }
            }
            //if we get an Instrument, return it
            if (ctacInstrument) {
                var instrumentObject = ctacTradeAudit[ctacInstrument];
                return instrumentObject;
            } else {
                return "not_found";
            }

        } else {
            return "not_found";
        }
    },
    _directionBuySell: function(allocationDirection) {
        //this function determines the direction of an allocation based on the SWB Payload
        var buyRegex = new RegExp("buy", "i");
        var sellRegex = new RegExp("sell", "i");

        if (allocationDirection.toString().match(buyRegex)) {
            return "B";
        } else if (allocationDirection.toString().match(sellRegex))
            return "S";
    },
    _getTradeCommission: function(tradeCharges) {
        //this function gets the Commission charges from the CTAC Payload for the Manual Allocations Instruction Handler

        if (tradeCharges) {
            for (let i = 0; i < tradeCharges.length; i++) {

                for (key in tradeCharges[i]) {

                    if (tradeCharges[i]['CHARGE_ID'].indexOf("ACOMMISSION") != -1) {
                        var chargeAmount = Number(tradeCharges[i].CHARGE_AMOUNT);
                    }
                }
            }
            if (chargeAmount) {
                return chargeAmount;
            } else {
                return "0.0";
            }
        } else {

            return "";
        }

    },
    type: 'IAWPayloadFormatter'
};
